import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Template cache for report generation
    private static final Map<String, String> TEMPLATES = new HashMap<>();

    static {
        TEMPLATES.put("sales", "SELECT product_name, quantity, price FROM sales WHERE region = '${region}' AND quarter = '${quarter}'");
        TEMPLATES.put("inventory", "SELECT sku, warehouse, stock_level FROM inventory WHERE warehouse_id = '${warehouse}'");
        TEMPLATES.put("audit", "SELECT event_type, actor, timestamp FROM audit_log WHERE actor = '${actor}' AND event_type = '${event_type}' ORDER BY timestamp DESC LIMIT ${limit}");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("report_type");
        if (reportType == null || !TEMPLATES.containsKey(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Collect all parameters for template substitution
        Map<String, String> params = new HashMap<>();
        req.getParameterMap().forEach((key, values) -> {
            if (!key.equals("report_type") && values.length > 0) {
                // Basic sanitization: strip semicolons and comments
                String cleaned = values[0].replaceAll(";", "").replaceAll("--", "");
                params.put(key, cleaned);
            }
        });

        // Apply template substitution
        String template = TEMPLATES.get(reportType);
        StringSubstitutor sub = new StringSubstitutor(params);
        String query = sub.replace(template);

        // Additional validation: reject if query contains multiple statements
        if (query.contains(";")) {
            resp.sendError(400, "Invalid characters in parameters");
            return;
        }

        // Execute and return results
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": \"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed: " + e.getMessage());
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("text/html");
        resp.getWriter().print("<html><body><h2>Report Service v2.3</h2>"
            + "<p>POST with report_type=[sales|inventory|audit] and relevant parameters</p>"
            + "</body></html>");
    }
}
